#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""FontAwesome per-app subsets — generate, verify and auto-extend.

Every app that uses icons carries an inline block:

    <style data-flove-inlined="fontawesome">
      /* Font Awesome 6.0.0-beta3 subset — N codepoints; generated by tools/fa-subset.py */
      @font-face{...base64 woff2...}
      .fa,.fa-solid,...{...}
      .fa-house:before{content:"\\f015"}
      ...
    </style>

The block carries only the icons that file renders, drawn from a shared kit:

    tools/fa/icons.json          name -> codepoint (all 2116 FA names)
    tools/fa/union.json          codepoints each union font carries
    tools/fa/union-solid.woff2   every solid icon any app uses
    tools/fa/union-regular.woff2 ditto, regular
    tools/fa/union-brands.woff2  ditto, brands

So regenerating is offline and deterministic: the file is the only input, the
kit the only source. When a file uses an icon the kit does not carry yet, the
script downloads the pinned Font Awesome release **once**, verifies its sha256,
subsets the new codepoint into the union and remembers it in `union.json` — the
icon is offline from then on (auto-extend).

Usage:
  python3 tools/fa-subset.py                 # verify (exit 1 on drift/gap)
  python3 tools/fa-subset.py --apply         # rewrite every block from its file
  python3 tools/fa-subset.py --fetch         # force re-download + rebuild the kit
  python3 tools/fa-subset.py --app apps/metas/goddy.html [--apply]

`fonttools` + `brotli` are needed only when the kit must grow (or with --fetch);
plain `--check`/`--apply` on a covered kit runs on the standard library.
"""
from __future__ import annotations

import argparse
import base64
import hashlib
import io
import json
import os
import re
import sys
import urllib.request

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
FA_DIR = os.path.join(ROOT, "tools", "fa")
ICONS_PATH = os.path.join(FA_DIR, "icons.json")
UNION_PATH = os.path.join(FA_DIR, "union.json")

FA_VERSION = "6.0.0-beta3"
CDN = "https://cdnjs.cloudflare.com/ajax/libs/font-awesome/" + FA_VERSION

# family -> (css family name, weight, union file, cdn path, sha256 of the cdn ttf)
FAMILIES = {
    "solid": ("Font Awesome 6 Free", 900, "union-solid.woff2",
              "webfonts/fa-solid-900.ttf",
              "1c210c134c340a1133991a605b0aac990ce8505c48fce37c915063402964e994"),
    "regular": ("Font Awesome 6 Free", 400, "union-regular.woff2",
                "webfonts/fa-regular-400.ttf",
                "e47616185481b0ecd636dc35fc4673a4a332b1ac96585fc1f9cf0d0553dac2a0"),
    "brands": ("Font Awesome 6 Brands", 400, "union-brands.woff2",
               "webfonts/fa-brands-400.ttf",
               "523dc72caa42687c946e5a8d7e6b438880a26881964466cf1425ce5114e49701"),
}

STYLE_TOKENS = {
    "fas": "solid", "fa-solid": "solid",
    "far": "regular", "fa-regular": "regular",
    "fab": "brands", "fa-brands": "brands",
}

BLOCK_RE = re.compile(r'([ \t]*)<style data-flove-inlined="fontawesome">(.*?)</style>\n?', re.S)
LINK_RE = re.compile(r'[ \t]*<link[^>]*href="[^"]*fontawesome/css/all\.min\.css"[^>]*>\n?')

BASE_RULES = [
    ".fa,.fa-solid,.fa-regular,.fa-brands,.fas,.far,.fab{-moz-osx-font-smoothing:grayscale;"
    "-webkit-font-smoothing:antialiased;display:var(--fa-display,inline-block);font-style:normal;"
    "font-variant:normal;line-height:1;text-rendering:auto}",
    '.fa{font-family:var(--fa-style-family,"Font Awesome 6 Free");font-weight:var(--fa-style,900)}',
]
FAMILY_RULES = {
    "solid": '.fa-solid,.fas{font-family:"Font Awesome 6 Free";font-weight:900}',
    "regular": '.fa-regular,.far{font-family:"Font Awesome 6 Free";font-weight:400}',
    "brands": '.fa-brands,.fab{font-family:"Font Awesome 6 Brands";font-weight:400}',
}


# ── kit ──────────────────────────────────────────────────────────────────────

def load_json(path, default):
    if not os.path.exists(path):
        return default
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)


def save_json(path, data):
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(data, fh, separators=(",", ":"))


def union_bytes(family):
    with open(os.path.join(FA_DIR, FAMILIES[family][2]), "rb") as fh:
        return fh.read()


def fetch_ttf(family):
    """Download the pinned TTF and verify its sha256."""
    url = f"{CDN}/{FAMILIES[family][3]}"
    print(f"  fetch {url}")
    with urllib.request.urlopen(url, timeout=60) as resp:
        data = resp.read()
    want = FAMILIES[family][4]
    got = hashlib.sha256(data).hexdigest()
    if got != want:
        raise SystemExit(f"sha256 mismatch for {url}\n  want {want}\n  got  {got}")
    return data


def extend_union(required):
    """Grow each union font so it covers `required`; fetches only what is missing."""
    have = load_json(UNION_PATH, {})
    changed = False
    for family, (_, _, filename, _, _) in FAMILIES.items():
        need = set(required.get(family, ()))
        covered = set(have.get(family, ()))
        missing = need - covered
        if not missing:
            continue
        try:
            from fontTools import subset as ftsubset
            from fontTools.ttLib import TTFont
        except ImportError:
            raise SystemExit("fonttools + brotli are required to grow the kit:\n"
                             "  pip install fonttools brotli")
        ttf = fetch_ttf(family)
        font = TTFont(io.BytesIO(ttf))
        cmap = set(font.getBestCmap().keys())
        keep = (covered | need) & cmap
        opts = ftsubset.Options()
        opts.flavor = "woff2"
        opts.glyph_names = False
        opts.notdef_outline = True
        opts.layout_features = ["*"]
        sub = ftsubset.Subsetter(options=opts)
        sub.populate(unicodes=sorted(keep))
        sub.subset(font)
        # deterministic output: never rewrite the head timestamps
        font.recalcTimestamp = False
        out = io.BytesIO()
        font.save(out)
        with open(os.path.join(FA_DIR, filename), "wb") as fh:
            fh.write(out.getvalue())
        have[family] = sorted(keep)
        changed = True
        print(f"  {filename}: {len(covered)} -> {len(keep)} codepoints ({len(out.getvalue())/1024:.1f} KB)")
        unknown = need - cmap
        if unknown:
            print(f"  note: {len(unknown)} codepoint(s) not in the {family} font: "
                  + ", ".join(hex(c) for c in sorted(unknown)))
    if changed:
        save_json(UNION_PATH, have)
    return have


# ── per-file analysis ────────────────────────────────────────────────────────

def strip_block(text):
    """Remove the existing icon block so the analysis never reads its own output."""
    return BLOCK_RE.sub("", text)


def used_icons(text, known):
    """family -> set(codepoints) for the icons this file renders.

    Family comes from the style token in the element/string that names the icon
    (`class="fab fa-github"`, `'fas fa-rotate'`); icons with no style token are
    solid, Font Awesome's default.
    """
    body = strip_block(text)
    fam = {k: set() for k in FAMILIES}
    for m in re.finditer(r"\b(fa-[a-z0-9-]+)\b", body):
        name = m.group(1)
        if name not in known:
            continue
        ctx = body[max(0, m.start() - 70):m.start()]
        style = None
        for tok in re.findall(r"\b(fas|far|fab|fa-solid|fa-regular|fa-brands)\b", ctx):
            style = STYLE_TOKENS[tok]
        fam[style or "solid"].add(known[name])
    return fam


def app_font(family, codepoints):
    """The app's own subset, cut from the union font (needs fonttools)."""
    covered = set(load_json(UNION_PATH, {}).get(family, ()))
    keep = sorted(set(codepoints) & covered)
    if len(keep) == len(covered):
        return union_bytes(family)          # app uses the whole union — reuse it
    return subset_woff2(union_bytes(family), keep)


def subset_woff2(src_bytes, codepoints):
    from fontTools import subset as ftsubset
    from fontTools.ttLib import TTFont
    opts = ftsubset.Options()
    opts.flavor = "woff2"
    opts.glyph_names = False
    opts.notdef_outline = True
    opts.layout_features = ["*"]
    font = TTFont(io.BytesIO(src_bytes))
    sub = ftsubset.Subsetter(options=opts)
    sub.populate(unicodes=sorted(codepoints))
    sub.subset(font)
    font.recalcTimestamp = False
    out = io.BytesIO()
    font.save(out)
    return out.getvalue()


def render_block(fam, indent):
    """Canonical inline block for one file (per-app subsets cut from the union)."""
    lines = [f'{indent}<style data-flove-inlined="fontawesome">']
    total = sum(len(v) for v in fam.values())
    lines.append(f"{indent}  /* Font Awesome {FA_VERSION} subset — {total} codepoints; "
                 f"generated by tools/fa-subset.py */")
    for family, (css_family, weight, filename, _, _) in FAMILIES.items():
        if not fam[family]:
            continue
        data = base64.b64encode(app_font(family, fam[family])).decode()
        lines.append(f'{indent}  @font-face{{font-family:"{css_family}";font-style:normal;'
                     f'font-weight:{weight};font-display:block;'
                     f'src:url(data:font/woff2;base64,{data}) format("woff2")}}')
    for rule in BASE_RULES:
        lines.append(indent + "  " + rule)
    for family in FAMILIES:
        if fam[family]:
            lines.append(indent + "  " + FAMILY_RULES[family])
    covered = set().union(*fam.values())
    for name, cp in sorted(load_json(ICONS_PATH, {}).items()):
        if cp in covered:
            lines.append(f'{indent}  .{name}:before{{content:"\\{cp:x}"}}')
    lines.append(f"{indent}</style>")
    return "\n".join(lines) + "\n"


def block_codepoints(text):
    block = BLOCK_RE.search(text)
    if not block:
        return None, set()
    return block, {int(cp, 16) for cp in re.findall(r'content:"\\([0-9a-f]+)"', block.group(2))}


# ── commands ─────────────────────────────────────────────────────────────────

def app_files(only):
    if only:
        return [only if os.path.isabs(only) else os.path.join(ROOT, only)]
    out = []
    for base in ("apps",):
        for dirpath, dirnames, filenames in os.walk(os.path.join(ROOT, base)):
            dirnames[:] = [d for d in dirnames if d not in {"node_modules", ".git"}]
            for name in filenames:
                if name.endswith(".html"):
                    out.append(os.path.join(dirpath, name))
    return sorted(out)


def main():
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--apply", action="store_true", help="rewrite the inline blocks")
    ap.add_argument("--fetch", action="store_true", help="re-download the pinned release and rebuild the kit")
    ap.add_argument("--app", help="limit to one file (repo-relative or absolute)")
    args = ap.parse_args()

    known = load_json(ICONS_PATH, {})
    plans = []
    for path in app_files(args.app):
        if not os.path.exists(path):
            continue
        text = open(path, encoding="utf-8", errors="ignore").read()
        if "data-flove-inlined=\"fontawesome\"" not in text and not LINK_RE.search(text):
            continue
        plans.append((path, text, used_icons(text, known)))
    if not plans:
        print("no files with a FontAwesome block")
        return 0

    required = {k: set() for k in FAMILIES}
    for _, _, fam in plans:
        for k in required:
            required[k] |= fam[k]

    if args.fetch:
        have = load_json(UNION_PATH, {})
        for family in FAMILIES:
            have.pop(family, None)
        save_json(UNION_PATH, have)
    extend_union(required)

    drift = []
    for path, text, fam in plans:
        rel = os.path.relpath(path, ROOT)
        link = LINK_RE.search(text)
        expected_cps = set().union(*fam.values())
        block, actual_cps = block_codepoints(text)
        if link:
            drift.append((rel, "still links all.min.css"))
            if args.apply:
                open(path, "w", encoding="utf-8").write(
                    text[:link.start()] + render_block(fam, "  ") + text[link.end():])
            continue
        if actual_cps != expected_cps:
            lost = sorted(hex(c) for c in expected_cps - actual_cps)
            extra = sorted(hex(c) for c in actual_cps - expected_cps)
            drift.append((rel, f"icons out of date (missing {lost[:3]}, extra {extra[:3]})"))
            if args.apply:
                open(path, "w", encoding="utf-8").write(
                    text[:block.start()] + render_block(fam, block.group(1)) + text[block.end():])
            continue
        # same icons: the fonts must still be the ones this kit produces
        if args.apply:
            expected = render_block(fam, block.group(1))
            if block.group(0).rstrip("\n") != expected.rstrip("\n"):
                open(path, "w", encoding="utf-8").write(
                    text[:block.start()] + expected + text[block.end():])
                print(f"  rebuilt  {rel}")
    if drift:
        for rel, why in drift:
            print(f"  drift  {rel}: {why}")
        print(f"{len(drift)} file(s) " + ("rewritten" if args.apply else "need --apply"))
        return 0 if args.apply else 1
    print(f"ok: {len(plans)} FontAwesome block(s) match tools/fa/")
    return 0


if __name__ == "__main__":
    sys.exit(main())
